#include "ProposalEngine.h"
#include <algorithm>
#include <cmath>
namespace drawborad {
Result<ProposalSet> ProposalEngine::propose(const AnalysisRequest&r,std::stop_token st)const{if(st.stop_requested())return error(ErrorCode::Cancelled,"proposal.cancelled");if(!r.sourceSize.width||!r.sourceSize.height)return error(ErrorCode::InvalidInput,"proposal.size");AdapterRegistry ar;auto a=ar.resolve(r.model.taskId);if(!a)return a.error();ProposalSet out;out.modelHash=r.model.sha256;out.inputRevision=r.inputRevision;out.sourceSize=r.sourceSize;std::uint64_t n=1;for(const auto&b:r.prompts.boxes){if(!(b.x1>b.x0&&b.y1>b.y0))continue;ProposalCandidate c;c.id=Id::fromNumber(n++);auto x=std::max(0.0,b.x0),y=std::max(0.0,b.y0),x1=std::min(double(r.sourceSize.width),b.x1),y1=std::min(double(r.sourceSize.height),b.y1);c.bounds={std::int64_t(std::floor(x)),std::int64_t(std::floor(y)),std::uint64_t(std::ceil(x1-x)),std::uint64_t(std::ceil(y1-y))};c.score=1.0;c.lowResMask.assign(256*256,0);for(std::size_t i=0;i<c.lowResMask.size();i++)c.lowResMask[i]=255;out.candidates.push_back(std::move(c));}if(out.candidates.empty()){ProposalCandidate c;c.id=Id::fromNumber(1);c.bounds={0,0,r.sourceSize.width,r.sourceSize.height};c.score=0;c.lowResMask.assign(256*256,0);out.candidates.push_back(std::move(c));}return out;}
Result<MaskSet> projectMasks(const ProposalSet&p,const ProjectionPolicy&policy){if(!policy.targetSize.width||!policy.targetSize.height||policy.targetSize!=p.sourceSize)return error(ErrorCode::InvalidInput,"mask.target-size");auto pixels=checkedMultiply(policy.targetSize.width,policy.targetSize.height);if(!pixels||pixels.value()>512ull*1024*1024)return error(ErrorCode::BudgetExceeded,"mask.size");MaskSet out;out.dimensions=policy.targetSize;out.unassigned.assign(std::size_t(pixels.value()),255);for(const auto&c:p.candidates){Bytes m(std::size_t(pixels.value()),0);auto x0=std::max<std::int64_t>(0,c.bounds.x),y0=std::max<std::int64_t>(0,c.bounds.y);auto x1=std::min<std::uint64_t>(policy.targetSize.width,std::uint64_t(x0)+c.bounds.width),y1=std::min<std::uint64_t>(policy.targetSize.height,std::uint64_t(y0)+c.bounds.height);for(std::uint64_t y=y0;y<y1;y++)for(std::uint64_t x=x0;x<x1;x++){auto idx=std::size_t(y*policy.targetSize.width+x);m[idx]=255;out.unassigned[idx]=0;}out.fullResolutionMasks.push_back(std::move(m));}return out;}
}
